param([string]$BaselineDirectory='',[string]$OutputDirectory='')
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../build/common.ps1')
. (Join-Path $PSScriptRoot '../build/recycle-send32-tests.ps1')
trap {$failure=$_;if($script:TestResultFile){Write-TestRecording 'failed'};throw $failure}
Initialize-BuildEnvironment
if($script:Version -cne '2.0.0'){throw 'Recycle send requires version 2.0.0'}
$script:SourceFingerprint=Get-SourceFingerprint;$utf8=[Text.UTF8Encoding]::new($false)
function Require-RcsHash([string]$Path,[string]$Hash){if($Hash -cnotmatch '^[a-f0-9]{64}$' -or (Get-FileHash -LiteralPath $Path).Hash.ToLowerInvariant() -cne $Hash){throw 'Recycle send raw hash differs'}}
function Require-RcsText([string]$Path,[string]$Text){if(![Linq.Enumerable]::SequenceEqual([byte[]][IO.File]::ReadAllBytes($Path),[byte[]]$utf8.GetBytes($Text))){throw 'Recycle send complete projection differs'}}
function Assert-RcsSet([string[]]$Actual,[string[]]$Expected,[string]$Message){$set=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($name in $Actual){if(!$set.Add($name)){throw $Message}};if($Actual.Count -ne $Expected.Count -or !$set.SetEquals($Expected)){throw $Message}}
[string[]]$production=@(rg --files driver common include);if($LASTEXITCODE){throw 'Cannot enumerate control production closure'}
[string[]]$dependencies=@($production|ForEach-Object {$_.Replace('\','/')})+@('wintun.props','tests/model/tun32_worker_pause_tests.c','tests/model/kernel_nbl_fixture.h','tests/model/control_reply_tests.c','tests/model/control_batch32_tests.c','tests/safety/guard_memory.h','tools/build/indication-pause-tests.ps1')
$directory=if(!$OutputDirectory){Join-Path $script:RepoRoot "out/recycle-send32/$($script:SourceFingerprint.Substring(0,12))"}elseif([IO.Path]::IsPathFullyQualified($OutputDirectory)){[IO.Path]::GetFullPath($OutputDirectory)}else{[IO.Path]::GetFullPath((Join-Path $script:RepoRoot $OutputDirectory))}
$historical=![string]::IsNullOrWhiteSpace($BaselineDirectory);$baselineIdentity=$null;$hashes=@{}
if($historical){
    $baseline=(Resolve-Path -LiteralPath $BaselineDirectory).Path;$manifestPath=Join-Path $baseline 'baseline.json';$manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json
    [string[]]$names=@($manifest.source_paths);[string[]]$sorted=$names.Clone();[Array]::Sort($sorted,[StringComparer]::Ordinal)
    if($names.Count -ne 727 -or ($names -join "`n") -cne ($sorted -join "`n") -or $manifest.version -cne '2.0.0' -or $manifest.source_fingerprint_order -cne 'typed string[] Ordinal'){throw 'Recycle send baseline count/order/version differs'}
    Assert-RcsSet $names @($manifest.files.PSObject.Properties.Name) 'Recycle send baseline file set differs'
    $entries=@(foreach($name in $names){Require-RcsHash (Join-Path $baseline $name) $manifest.files.$name;$name+':'+$manifest.files.$name})
    $baselineIdentity=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($utf8.GetBytes(($entries -join "`n")))).ToLowerInvariant()
    if($baselineIdentity -cne '4c7c7832d59cc9cd09e8b480eb902aea3ae6c26979c688d26db9dccfed0c168b' -or $manifest.source_tree_sha256 -cne $baselineIdentity){throw 'Recycle send baseline identity differs'}
    Assert-RcsSet @($production|ForEach-Object {$_.Replace('\','/')}) @($names|Where-Object {$_ -cmatch '^(driver|common|include)/'}) 'Recycle send baseline production set differs'
    foreach($relative in $dependencies){$hashes[$relative]=$manifest.files.$relative}
}else{
    $baseline=Join-Path $directory 'current-source';foreach($relative in $dependencies){$source=Join-Path $script:RepoRoot $relative;$copy=Join-Path $baseline $relative;New-Item -ItemType Directory -Path (Split-Path $copy) -Force|Out-Null;[IO.File]::WriteAllBytes($copy,[IO.File]::ReadAllBytes($source));$hashes[$relative]=(Get-FileHash $source).Hash.ToLowerInvariant()}
    $manifestPath=Join-Path $baseline 'snapshot.json';@{version=$script:Version;source_tree_sha256=$script:SourceFingerprint;files=$hashes}|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $manifestPath -Encoding utf8
}
New-Item -ItemType Directory -Path $directory -Force|Out-Null
function Assert-RcsDependencies {foreach($relative in $dependencies){Require-RcsHash (Join-Path $baseline $relative) $hashes[$relative];Require-RcsHash (Join-Path $script:RepoRoot $relative) $hashes[$relative]}}
Assert-RcsDependencies
function Assert-RcsBuild($build){
    if($build.ip_version -notin 4,6 -or $build.mode -cnotin 'iso','ms' -or $build.guarded -isnot [bool]){throw 'Recycle send build selection differs'}
    $place=[IO.Path]::GetDirectoryName($build.path);$test=Join-Path $script:RepoRoot 'tests/model/recycle_send32_tests.c'
    if($build.path -cne (Join-Path $place 'recycle-send32.exe') -or $build.entry -cne (Join-Path $place 'entry.c') -or $build.test -cne $test){throw 'Recycle send output/test binding differs'}
    Require-RcsHash $build.path $build.sha256;Require-RcsHash $build.entry $build.entry_sha256;Require-RcsHash $test $build.test_sha256
    $original=Join-Path $script:RepoRoot 'tests/model/kernel_nbl_fixture.h';$hash='c236a169004e4851111c1000353b85685dbe92b32191e8cb28509989f19d0eb3';$e=$build.extractions
    if($e.host_source -cne $original -or $e.host_source_sha256 -cne $hash -or $e.host_original_sha256 -cne $hash){throw 'Recycle send original kernel metadata differs'}
    Require-RcsHash $original $hash;Require-RcsHash $e.host_original $hash;Require-RcsHash $e.host $e.host_sha256
    $body=[IO.File]::ReadAllText($original);$marker='        EX_RUNDOWN_REF ReturnRundown;';$fields='        KSPIN_LOCK IndicationLock; KEVENT IndicationIdle[2]; ULONG IndicationBank; LONG IndicationCount[2];'
    if([regex]::Matches($body,[regex]::Escape($marker)).Count -ne 1){throw 'Recycle send bank fields anchor not unique'};$body=$body.Replace($marker,$marker+"`r`n"+$fields)
    $body=[regex]::Replace($body,'(?m)^#include "([^"]+)"',{param($m)'#include "'+[IO.Path]::GetFullPath((Join-Path (Split-Path $original) $m.Groups[1].Value)).Replace('\','/')+'"'})
    Require-RcsText $e.host $body
    $expected=[ordered]@{outer=@('driver/wintun.c','static MINIPORT_RETURN_NET_BUFFER_LISTS TunReturnNetBufferLists;','#define TUN_FORCE_UNREGISTRATION');tunpause=@('driver/wintun.c','static MINIPORT_PAUSE TunPause;','static MINIPORT_DEVICE_PNP_EVENT_NOTIFY TunDevicePnPEventNotify;');receive=@('driver/v2/session_receive.h','static BOOLEAN PbV2ReceiveBatch(','[end]');gate=@('driver/v2/indication_gate.h','[whole]','[end]');pause=@('driver/v2/session_pause.h','[whole]','[end]')}
    if($e.variant -cne 'current'){throw 'Recycle send requires current production bodies'};Assert-RcsSet @($e.parts|ForEach-Object {$_.name}) @($expected.Keys) 'Recycle send actual part set differs'
    foreach($part in $e.parts){$spec=$expected[$part.name];$source=Join-Path $script:RepoRoot $spec[0];$body=[IO.File]::ReadAllText($source);$start=if($spec[1] -ceq '[whole]'){0}else{$body.IndexOf($spec[1])};$end=if($spec[2] -ceq '[end]'){$body.Length}else{$body.IndexOf($spec[2],$start)}
        if($start -lt 0 -or $end -le $start -or $part.source -cne $source -or $part.offset -ne $start -or $part.length -ne $end-$start){throw 'Recycle send actual span binding differs'}
        Require-RcsHash $source $part.source_sha256;Require-RcsHash $part.path $part.sha256;Require-RcsText $part.path $body.Substring($start,$end-$start)
    }
    $specs=[ordered]@{restart=@('driver/wintun.c','static MINIPORT_RESTART TunRestart;','static MINIPORT_PAUSE TunPause;');reply=@('driver/v2/session.h','static NDIS_STATUS PbV2ControlReply(','#include "session_describe.h"');frame=@('tests/model/control_reply_tests.c','static VOID Put16(','static VOID RunControl(')}
    Assert-RcsSet @($build.spans|ForEach-Object {$_.name}) @($specs.Keys) 'Recycle send extra span set differs'
    foreach($part in $build.spans){$spec=$specs[$part.name];$source=Join-Path $script:RepoRoot $spec[0];$body=[IO.File]::ReadAllText($source);foreach($marker in $spec[1..2]){if([regex]::Matches($body,[regex]::Escape($marker)).Count -ne 1){throw 'Recycle send markers not unique'}};$start=$body.IndexOf($spec[1]);$end=$body.IndexOf($spec[2],$start)
        if($part.source -cne $source -or $part.path -cne (Join-Path $place "$($part.name)-original.h") -or $part.snapshot -cne (Join-Path $place "$($part.name)-source-original") -or $part.offset -ne $start -or $part.length -ne $end-$start -or $part.start_marker -cne $spec[1] -or $part.end_marker -cne $spec[2] -or $part.source_sha256 -cne $part.snapshot_sha256){throw 'Recycle send extra span binding differs'}
        if($part.name -ceq 'frame' -and $part.source_sha256 -cne '70492226145283c68ab9036053a65bef96827a2b49d850da41087ba0ba013d7e'){throw 'Recycle send frozen frame source differs'}
        Require-RcsHash $source $part.source_sha256;Require-RcsHash $part.snapshot $part.snapshot_sha256;Require-RcsHash $part.path $part.sha256;Require-RcsText $part.path $body.Substring($start,$end-$start)
    }
    Assert-RcsSet @($build.types|ForEach-Object {$_.name}) @('nblchecksum','nbllso','nbluso') 'Recycle send WDK type set differs';$typeBodies=@()
    foreach($name in 'nblchecksum','nbllso','nbluso'){$part=@($build.types|Where-Object name -ceq $name)[0];$source=Join-Path $script:WdkRoot "Include/$script:KitVersion/km/ndis/$name.h";$body=[IO.File]::ReadAllText($source);$matches=[regex]::Matches($body,'(?s)typedef struct _NDIS_.*?\n\} NDIS_[^;]+;');if($matches.Count -ne 1){throw 'Recycle send WDK type not unique'};$match=$matches[0];$typeBodies+=$match.Value
        if($part.source -cne $source -or $part.snapshot -cne (Join-Path $place "wdk-$name-original.h") -or $part.source_sha256 -cne $part.snapshot_sha256 -or $part.offset -ne $match.Index -or $part.length -ne $match.Length -or $part.span_sha256 -cne [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($utf8.GetBytes($match.Value))).ToLowerInvariant()){throw 'Recycle send WDK type binding differs'};Require-RcsHash $source $part.source_sha256;Require-RcsHash $part.snapshot $part.snapshot_sha256
    }
    if($build.type_path -cne (Join-Path $place 'types.h')){throw 'Recycle send aggregate type path differs'};Require-RcsHash $build.type_path $build.type_sha256;Require-RcsText $build.type_path ($typeBodies -join "`n")
    $hostSource=Join-Path $script:RepoRoot 'tests/model/tun32_worker_pause_tests.c';$hash='a0a20ebbe48fdcfbf64a0f210dcafcc107e0e83cf060c4727df6301653808771'
    if($build.host_source -cne $hostSource -or $build.host_source_sha256 -cne $hash -or $build.host_original_sha256 -cne $hash -or $build.host_original -cne (Join-Path $place 'worker-host-original.c') -or $build.host -cne (Join-Path $place 'worker-host.h')){throw 'Recycle send frozen worker host binding differs'}
    Require-RcsHash $hostSource $hash;Require-RcsHash $build.host_original $hash;Require-RcsHash $build.host $build.host_sha256
    $body=[regex]::Replace([IO.File]::ReadAllText($hostSource),'(?m)^#include "([^"]+)"',{param($m)'#include "'+[IO.Path]::GetFullPath((Join-Path (Split-Path $hostSource) $m.Groups[1].Value)).Replace('\','/')+'"'});Require-RcsText $build.host $body
    $control=Join-Path $script:RepoRoot 'tests/model/control_batch32_tests.c';$hash='871a9469fb0d5c20433e5dcc853e2178818b161b6134143aeda38e5dd3dccf53'
    if($build.control_source -cne $control -or $build.control_source_sha256 -cne $hash -or $build.control_original_sha256 -cne $hash -or $build.control_original -cne (Join-Path $place 'control-host-original.c') -or $build.control_host -cne (Join-Path $place 'control-host.h') -or $build.callout_observer -cne (Join-Path $place 'callout-observe.h') -or $build.send_observer -cne (Join-Path $place 'send-observe.h')){throw 'Recycle send frozen control host binding differs'}
    Require-RcsHash $control $hash;Require-RcsHash $build.control_original $hash;Require-RcsHash $build.control_host $build.control_host_sha256;Require-RcsHash $build.callout_observer $build.callout_observer_sha256;Require-RcsHash $build.send_observer $build.send_observer_sha256
    $lines=@('static VOID RcsSdkComplete(NDIS_HANDLE,NET_BUFFER_LIST *,ULONG);','#define NdisMSendNetBufferListsComplete RcsSdkComplete',('#include "'+(Join-Path $script:RepoRoot 'driver/v2/ndis_callouts.h').Replace('\','/')+'"'),'#undef NdisMSendNetBufferListsComplete');Require-RcsText $build.callout_observer (($lines -join "`n")+"`n")
    $lines=@('static PB_RESULT RcsReserve(PB_POOL *,PB_TOKEN *);','static VOID RcsReject(TUN_CTX *,uint64_t,NET_BUFFER_LIST *,NET_BUFFER *,NDIS_STATUS,ULONG,ULONG,ULONG,const PB_SEND_FAILURE *,ULONG,ULONG,ULONG,PB_KERNEL_QUEUE *,ULONG);','#pragma push_macro("PbV2RejectSend")','#undef PbV2RejectSend','#define PbV2RejectSend RcsReject','#define PbPoolReserve RcsReserve',('#include "'+(Join-Path $script:RepoRoot 'driver/v2/session_send.h').Replace('\','/')+'"'),'#undef PbPoolReserve','#pragma pop_macro("PbV2RejectSend")');Require-RcsText $build.send_observer (($lines -join "`n")+"`n")
    $body=[IO.File]::ReadAllText($control);if([regex]::Matches($body,[regex]::Escape('int main(VOID)')).Count -ne 1){throw 'Recycle send old entry anchor not unique'}
    $body=[regex]::Replace($body,'(?m)^#include "([^"]+)"',{param($m)$relative=$m.Groups[1].Value;$path=if($relative -ceq '../../driver/v2/ndis_callouts.h'){$build.callout_observer}elseif($relative -ceq '../../driver/v2/session_send.h'){$build.send_observer}else{[IO.Path]::GetFullPath((Join-Path (Split-Path $control) $relative))};'#include "'+$path.Replace('\','/')+'"'}).Replace('int main(VOID)','int UnusedRecycleControlMain(VOID)');Require-RcsText $build.control_host $body
    $helper=Join-Path $script:RepoRoot 'tools/build/indication-pause-tests.ps1';if([IO.Path]::GetFullPath($build.helper.path) -cne [IO.Path]::GetFullPath($helper)){throw 'Recycle send helper binding differs'};Require-RcsHash $helper $build.helper.sha256
    Assert-RcsSet @($build.production|ForEach-Object {$_.relative}) $production 'Recycle send production closure set differs'
    foreach($p in $build.production){$source=Join-Path $script:RepoRoot $p.relative;$copy=Join-Path $place ('source-'+$p.relative.Replace('\','-').Replace('/','-'));if($p.source -cne $source -or $p.path -cne $copy -or $p.source_sha256 -cne $p.sha256){throw 'Recycle send raw production binding differs'};Require-RcsHash $source $p.source_sha256;Require-RcsHash $copy $p.sha256}
    $flags=@('/nologo','/std:c17','/MT','/O2','/W4','/WX','/DNDEBUG','/D_WIN32_WINNT=0x0601','/DNTDDI_VERSION=0x06010000',"/volatile:$($build.mode)","/Fo$place\")+@($script:VersionArguments|Where-Object {$_ -notlike '/DPB_SOURCE_FINGERPRINT=*'})+"/DPB_SOURCE_FINGERPRINT=$script:SourceFingerprint"
    if(($flags -join "`n") -cne ($build.arguments -join "`n")){throw 'Recycle send compile arguments differ'}
    $lines=@();if($build.guarded){$lines+='#define PB_GUARD_TESTS 1'};$lines+='#define PB_TEST_IP_VERSION '+$build.ip_version;$bindings=[ordered]@{PB_RCS_CONTROL=$build.control_host;PB_BATCH_HOST=$build.host;PB_BATCH_TYPES=$build.type_path;PB_BATCH_REPLY=($build.spans|Where-Object name -ceq 'reply').path;PB_BATCH_FRAME=($build.spans|Where-Object name -ceq 'frame').path;PB_WP_HOST=$e.host;PB_WP_RESTART=($build.spans|Where-Object name -ceq 'restart').path;PB_REFERENCE_SOURCE=(Join-Path $script:RepoRoot 'driver/v2/session_references.h');PB_NBL_SOURCE=(Join-Path $script:RepoRoot 'driver/v2/session_nbl.h')}
    foreach($name in $bindings.Keys){$lines+='#define '+$name+' "'+$bindings[$name].Replace('\','/')+'"'};foreach($part in $e.parts){$lines+='#define PB_WP_'+$part.name.ToUpperInvariant()+' "'+$part.path.Replace('\','/')+'"'};$lines+='#include "'+$test.Replace('\','/')+'"';Require-RcsText $build.entry (($lines -join "`n")+"`n")
}
function Read-RcsMetrics([string[]]$Lines,[int]$Family){
    $text=$Lines -join "`n";$rows=[regex]::Matches($text,'(?m)^RECYCLE_SEND32 ip([46]) proto(6|17) ndis(20|89) wrap([01]) measured([01]) sends32/32/32 rx32 recycle32 bad17 free16 published16 reserve33 payload48000 prefix3835 wake1/1/1 returned16/16 rxRetired32 rxComplete0 joins3 owners0 repairs0$')
    if($rows.Count -ne 16 -or @($Lines|Where-Object {$_ -like 'RECYCLE_SEND32 *'}).Count -ne 16){throw 'Recycle send case count/format differs'}
    for($i=0;$i -lt 16;++$i){$shape=$i%8;$protocol=if($shape -lt 4){6}else{17};$minor=if(([int][Math]::Floor($shape/2)%2) -eq 0){20}else{89};$g=$rows[$i].Groups
        if([int]$g[1].Value -ne $Family -or [int]$g[2].Value -ne $protocol -or [int]$g[3].Value -ne $minor -or [int]$g[4].Value -ne $shape%2 -or [int]$g[5].Value -ne [int]($i -ge 8)){throw 'Recycle send family/matrix differs'}
    }
    $summary=[regex]::Matches($text,'(?m)^PASS: RECYCLE_SEND32 family([46]) cases16 warm8 measured8 joins48 workerJoins16 handles(\d+)/(\d+) owners0 repairs0$')
    if($summary.Count -ne 1 -or @($Lines|Where-Object {$_ -like 'PASS:*'}).Count -ne 1 -or [int]$summary[0].Groups[1].Value -ne $Family -or $summary[0].Groups[2].Value -cne $summary[0].Groups[3].Value){throw 'Recycle send summary/resources differ'}
    return @{cases=16;warm=8;measured=8;joined_threads=48;idle_native_worker_joins=16;native_return_os_thread_joins=32;send_originals=16*96;receive_originals=16*32;tx_prefix_retired=16*16;tx_suffix_abandoned=16*16;payload_reads=16*32;payload_read_bytes=16*48000;classification_reads=16*65;classification_read_bytes=16*3835;reserve_calls=16*33;rx_private_retired=16*32;rx_completed=0;process_handles_before=[int]$summary[0].Groups[2].Value;process_handles_after=[int]$summary[0].Groups[3].Value}
}
Start-TestRecording $directory 'operations.json'
function Invoke-RcsProcess($build){
    $info=[Diagnostics.ProcessStartInfo]::new($build.path);$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$p=[Diagnostics.Process]::new();$p.StartInfo=$info
    try{if(!$p.Start()){throw 'Cannot start recycle send test'};$stdout=$p.StandardOutput.ReadToEndAsync();$stderr=$p.StandardError.ReadToEndAsync();if(!$p.WaitForExit(60000)){$p.Kill($true);$p.WaitForExit();throw 'Recycle send external watchdog expired'}
        $output=$stdout.GetAwaiter().GetResult()+$stderr.GetAwaiter().GetResult();$log=Join-Path $script:TestLogDirectory ('{0:d2}-ipv{1}-{2}-{3}.log' -f $script:TestExecutions.Count,$build.ip_version,$build.mode,$build.guarded);[IO.File]::WriteAllText($log,$output,$utf8)
        $row=[ordered]@{program=$build.path;arguments=@();exit_code=$p.ExitCode;ip_version=$build.ip_version;mode=$build.mode;guarded=$build.guarded;log=$log;log_sha256=(Get-FileHash $log).Hash.ToLowerInvariant();reported_pass_messages=@($output -split '\r?\n'|Where-Object {$_.StartsWith('PASS:')})};$script:TestExecutions.Add($row);Write-TestRecording $(if($p.ExitCode){'failed'}else{'running'})
        if($p.ExitCode){throw "Recycle send exit$($p.ExitCode): $log"};$row['metrics']=Read-RcsMetrics @($output -split '\r?\n') $build.ip_version;Write-Output $row.reported_pass_messages
    }finally{$p.Dispose()}
}
$builds=@();$firstBuild=$null
foreach($family in 4,6){foreach($mode in 'iso','ms'){foreach($guard in $false,$true){
    $build=Build-RecycleSend32Tests -Directory (Join-Path $directory "ipv$family-$mode-guard$guard") -IpVersion $family -Mode $mode -Guarded:$guard
    if($build.ip_version -ne $family -or $build.mode -cne $mode -or $build.guarded -ne $guard){throw 'Recycle send requested build differs'};Assert-RcsBuild $build;$builds+=$build;if(!$firstBuild){$firstBuild=$build};Invoke-RcsProcess $build
}}}
$parser=@();[string[]]$original=Get-Content -LiteralPath $script:TestExecutions[0].log;Read-RcsMetrics $original 4|Out-Null
foreach($kind in 'wrong-family','missing-row','duplicate-row','extra-payload-copy'){
    $changed=switch($kind){'wrong-family'{@($original|ForEach-Object {$_ -replace '^RECYCLE_SEND32 ip4 ','RECYCLE_SEND32 ip6 '})}'missing-row'{@($original|Where-Object {$_ -notmatch '^RECYCLE_SEND32 ip4 proto6 ndis20 wrap0 measured0 '})}'duplicate-row'{@($original)+@($original|Where-Object {$_ -like 'RECYCLE_SEND32 *'}|Select-Object -First 1)}'extra-payload-copy'{@($original|ForEach-Object {$_ -replace 'payload48000','payload96000'})}}
    $expected=if($kind -eq 'wrong-family'){'Recycle send family/matrix differs'}else{'Recycle send case count/format differs'};$reason=$null;try{Read-RcsMetrics $changed 4|Out-Null}catch{$reason=$_.Exception.Message}
    if($reason -cne $expected){throw "Recycle send parser wrong rejection: $kind ($reason)"};$parser+=@{name=$kind;rejected=$true;reason=$reason}
}
$metadata=@();Assert-RcsBuild ($firstBuild|ConvertTo-Json -Depth 20|ConvertFrom-Json)
foreach($kind in 'duplicate-dependency','duplicate-part','part-source-hash','host-source','compile-flags'){
    $changed=$firstBuild|ConvertTo-Json -Depth 20|ConvertFrom-Json
    $expected=switch($kind){'duplicate-dependency'{$changed.production[1]=$changed.production[0];'Recycle send production closure set differs'}'duplicate-part'{$changed.extractions.parts[1]=$changed.extractions.parts[0];'Recycle send actual part set differs'}'part-source-hash'{$changed.extractions.parts[0].source_sha256='0'*64;'Recycle send raw hash differs'}'host-source'{$changed.host_source=Join-Path $script:RepoRoot 'tests/model/return_coalesce_tests.c';'Recycle send frozen worker host binding differs'}'compile-flags'{$changed.arguments=@($changed.arguments)+'/DPB_API_TESTS=1';'Recycle send compile arguments differ'}}
    $reason=$null;try{Assert-RcsBuild $changed}catch{$reason=$_.Exception.Message};if($reason -cne $expected){throw "Recycle send metadata wrong rejection: $kind ($reason)"};$metadata+=@{name=$kind;rejected=$true;reason=$reason}
}
$contracts=@();$originalEntry=[IO.File]::ReadAllText($firstBuild.entry)
foreach($kind in 'api-test','assertions','mixed-family','fingerprint'){
    $place=Join-Path $directory "compiler-$kind";New-Item -ItemType Directory -Path $place -Force|Out-Null;$text=$originalEntry;$flags=@($firstBuild.arguments|Where-Object {$_ -notlike '/Fo*'})
    $message=switch($kind){'api-test'{$flags+='/DPB_API_TESTS=1';'Shipping recycle send paths required'}'assertions'{$flags=@($flags|Where-Object {$_ -ne '/DNDEBUG'});'Shipping recycle send configuration required'}'mixed-family'{$text=$text.Replace('#define PB_TEST_IP_VERSION 4','#define PB_TEST_IP_VERSION 0');'Select one IP family'}'fingerprint'{$flags=@($flags|Where-Object {$_ -notlike '/DPB_SOURCE_FINGERPRINT=*'});'recycle send requires shipping fingerprint'}}
    $entry=Join-Path $place 'entry.c';[IO.File]::WriteAllText($entry,$text,$utf8);$log=Join-Path $place 'compile.log';& cl.exe @flags /c $entry "/Fo$place\entry.obj" *> $log;$code=$LASTEXITCODE
    if(!$code -or !([regex]::IsMatch([IO.File]::ReadAllText($log),'(?m)error C(?:1189|2338):[^\r\n]*'+[regex]::Escape($message)))){throw "Recycle send exact compiler guard failed: $kind"}
    $contracts+=@{name=$kind;exit_code=$code;expected_failure=$true;guard_message=$message;arguments=$flags;entry=$entry;entry_sha256=(Get-FileHash $entry).Hash.ToLowerInvariant();log=$log;log_sha256=(Get-FileHash $log).Hash.ToLowerInvariant()}
